(* [comment removed for export] *)
Lemma er_H : forall regs m (s sel data row i j pixd pixt w h cx cy : Z),
  (128 <= s)%Z -> (s < 2 ^ 64)%Z ->
  (0 <= sel)%Z -> (sel + 24 <= 2 ^ 64)%Z -> (0 <= data)%Z -> (data + 8 * i + 8 <= 2 ^ 64)%Z -> (0 <= row)%Z -> (row + 4 * j + 4 <= 2 ^ 64)%Z ->
  (0 <= i < 2 ^ 30)%Z -> (0 <= j < 2 ^ 30)%Z -> (0 <= cx < 2 ^ 30)%Z -> (0 <= cy < 2 ^ 30)%Z -> (0 <= w < 2 ^ 31)%Z -> (0 <= h < 2 ^ 31)%Z ->
  (0 <= pixt < 2 ^ 64)%Z ->
  rdn SEGS m (Z_to_bv 64 (sel + 16)) 8 = Some (Z_to_le_bytes 8 data) ->
  rdn SEGS m (Z_to_bv 64 (data + 8 * i)) 8 = Some (Z_to_le_bytes 8 row) ->
  rdn SEGS m (Z_to_bv 64 (row + 4 * j)) 4 = Some (Z_to_le_bytes 4 1) ->
  rdn SEGS m (Z_to_bv 64 (s - 92)) 4 = Some (Z_to_le_bytes 4 cx) -> rdn SEGS m (Z_to_bv 64 (s - 96)) 4 = Some (Z_to_le_bytes 4 cy) ->
  rdn SEGS m (Z_to_bv 64 (s - 76)) 4 = Some (Z_to_le_bytes 4 w) -> rdn SEGS m (Z_to_bv 64 (s - 80)) 4 = Some (Z_to_le_bytes 4 h) ->
  rdn SEGS m (Z_to_bv 64 (s - 120)) 8 = Some (Z_to_le_bytes 8 pixt) ->
  store_ok SEGS m (Z_to_bv 64 (s - 128)) 8 = true ->
  getr regs 2 = Z_to_bv 64 (s - 128) -> getr regs 9 = Z_to_bv 64 sel -> getr regs 8 = Z_to_bv 64 pixd ->
  getr regs 18 = Z_to_bv 64 i -> getr regs 19 = Z_to_bv 64 1 -> getr regs 20 = Z_to_bv 64 (4 * j) -> getr regs 21 = Z_to_bv 64 (- j) ->
  getr regs 23 = Z_to_bv 64 (8 * i) ->
  exists regs',
    msteps SEGS (mkst regs (0x8f988 : word) m rom) (mkst regs' (0x797ac : word) (SARE m s) rom)
    /\ getr regs' 1 = Z_to_bv 64 0x8f9d0 /\ getr regs' 10 = Z_to_bv 64 pixd /\ getr regs' 11 = Z_to_bv 64 (cx - j)
    /\ getr regs' 12 = Z_to_bv 64 (cy - i) /\ getr regs' 13 = Z_to_bv 64 w /\ getr regs' 14 = Z_to_bv 64 h
    /\ getr regs' 15 = Z_to_bv 64 8 /\ getr regs' 16 = Z_to_bv 64 pixt /\ getr regs' 17 = Z_to_bv 64 0
    /\ regs_agree (fun r => In r [1; 10; 11; 12; 13; 14; 15; 16; 17]%list) regs regs'.
