(* [comment removed for export] *)
Lemma er_T : forall regs m (s sel : Z),
  (128 <= s)%Z -> (s < 2 ^ 64)%Z -> rdn SEGS m (Z_to_bv 64 0x1137e8) 4 = Some (Z_to_le_bytes 4 1) ->
  getr regs 2 = Z_to_bv 64 (s - 128) -> getr regs 9 = Z_to_bv 64 sel ->
  exists regs',
    msteps SEGS (mkst regs (0x8f9d8 : word) m rom) (mkst regs' (0x92bac : word) m rom)
    /\ getr regs' 1 = Z_to_bv 64 0x8fa00 /\ getr regs' 10 = Z_to_bv 64 sel /\ getr regs' 11 = Z_to_bv 64 (s - 100)
    /\ getr regs' 12 = Z_to_bv 64 (s - 104) /\ getr regs' 13 = Z_to_bv 64 (s - 108) /\ getr regs' 14 = Z_to_bv 64 (s - 112)
