Lemma er_X2c : forall regs m (s pixd xn w h : Z), (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= xn < 2 ^ 30)%Z -> (0 <= w < 2 ^ 30)%Z -> (0 <= h < 2 ^ 31)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 108)) 4 = Some (Z_to_le_bytes 4 xn) -> rdn SEGS m (Z_to_bv 64 (s - 76)) 4 = Some (Z_to_le_bytes 4 w) ->
  rdn SEGS m (Z_to_bv 64 (s - 80)) 4 = Some (Z_to_le_bytes 4 h) ->
  store_ok SEGS m (Z_to_bv 64 (s - 128)) 8 = true -> getr regs 2 = Z_to_bv 64 (s - 128) -> getr regs 8 = Z_to_bv 64 pixd ->
  exists regs', msteps SEGS (mkst regs (0x8fa2c : word) m rom) (mkst regs' (0x797ac : word) (SARE m s) rom)
    /\ getr regs' 1 = Z_to_bv 64 0x8fa5c /\ getr regs' 10 = Z_to_bv 64 pixd /\ getr regs' 11 = Z_to_bv 64 (w - xn) /\ getr regs' 12 = Z_to_bv 64 0
    /\ getr regs' 13 = Z_to_bv 64 xn /\ getr regs' 14 = Z_to_bv 64 h /\ getr regs' 15 = Z_to_bv 64 0 /\ getr regs' 16 = Z_to_bv 64 0
